nta.declaration:
// MellowProtocol: autômato temporizado M_tau (Capítulo 3) para o UPPAAL 4.1 ou 5.x.
// Escala de tempo abstrata: os prazos absolutos de P são substituídos por constantes
// inteiras pequenas que respeitam t0 = 0 < TA < TF < TE. O valor v é abstraído para V = 10;
// S1 e S2 são lineares em v, e a escolha de V não altera o resultado.
const int TA    = 3;   // tau_aceite
const int TF    = 6;   // tau_financ
const int TE    = 20;  // tau_exec
const int DI    = 5;   // Delta t_insp
const int TDISP = 7;   // H1: prazo do árbitro
const int EPS   = 1;   // H2: latência máxima de inclusão de sigma_7
const int V     = 10;  // v
const int TMAX  = TE + DI + TDISP + 2*EPS;  // Equação de T_max com t0 = 0

template.declaration:
// Relógios de M_tau: x0 (iniciado em t0, nunca reiniciado) e xent (reiniciado em sigma_4).
// xd é relógio auxiliar de observação, usado apenas para impor a premissa H1.
clock x0, xent, xd;
int B = 0;        // saldo acumulado B(rho) = soma(e_in - e_out)
int pagoP = 0;    // total transferido a alpha_p
int pagoC = 0;    // total transferido a alpha_c
int liq = 0;      // número de liquidações (transições com e_out > 0)
